#include "hl2modelib.h"
#include <stdio.h>
#include <string.h>
#define MAX 8*1024*1024
static hl2m_u8 a[MAX],b[MAX],c[MAX];static hl2m_mdl mdl;static hl2m_vvd vvd;static hl2m_vtx vtx;static hl2m_engine_model eng;
static int load(const char *p,hl2m_u8 *v,unsigned int *n,int f){FILE *fp=fopen(p,"rb");int x=0;if(!fp)return 1;*n=(unsigned int)fread(v,1,MAX-1,fp);fclose(fp);return hl2m_repair_missing_first_byte(v,n,MAX,f,&x);}
int main(int argc,char **argv){unsigned int an,bn,cn;int i,j,sum=0; if(argc!=4)return 10;if(load(argv[1],a,&an,HL2M_FORMAT_MDL)||load(argv[2],b,&bn,HL2M_FORMAT_VVD)||load(argv[3],c,&cn,HL2M_FORMAT_VTX))return 11;if(hl2m_decode_mdl(a,an,&mdl)||hl2m_decode_vvd(b,bn,0,&vvd)||hl2m_decode_vtx(c,cn,&vtx))return 12;if(hl2m_build_engine_model(&mdl,&vvd,&vtx,0,&eng))return 13;printf("models=%d meshes=%d fixups=%d vdverts=%d tri=%d\n",mdl.model_count,mdl.mesh_count,vvd.fixup_count,vvd.vertex_count,eng.index_count/3);for(i=0;i<mdl.model_count;i++){printf("MODEL %d verts=%d base_by_sum=%d base_sdk=%d tangent_sdk=%d\n",i,mdl.models[i].numvertices,sum,mdl.models[i].vertexindex/48,mdl.models[i].tangentsindex/16);sum+=mdl.models[i].numvertices;}for(i=0;i<mdl.mesh_count;i++)printf("mesh %d: model %d voff %d vcount %d material %d\n",i,mdl.meshes[i].model_index,mdl.meshes[i].vertexoffset,mdl.meshes[i].numvertices,mdl.meshes[i].material);for(i=0;i<vvd.fixup_count&&i<15;i++)printf("fixup lod=%d start=%d len=%d\n",vvd.fixups[i].lod,vvd.fixups[i].source_vertex_id,vvd.fixups[i].num_vertices);for(i=0;i<eng.draw_count;i++){int mn=2147483647,mx=-2147483647;for(j=eng.draws[i].first_vertex;j<eng.draws[i].first_vertex+eng.draws[i].num_vertices;j++){int u=eng.vertices[j].texcoord.x,v=eng.vertices[j].texcoord.y;if(u<mn)mn=u;if(u>mx)mx=u;if(v<mn)mn=v;if(v>mx)mx=v;}printf("DRAW %d %s verts=%d uv_minQ=%d maxQ=%d\n",i,eng.draws[i].material_name,eng.draws[i].num_vertices,mn,mx);}return 0;}
